// Adjusts the Android project generated by `npx cap add android`:
// Bluetooth permissions, full-screen keep-awake activity, version numbers, icon and splash.
// Env: VERSION_NAME (e.g. 0.6.0), VERSION_CODE (monotonic integer, e.g. the CI run number).
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { crc32, deflateSync } from 'node:zlib';

const here = dirname(fileURLToPath(import.meta.url));
const config = JSON.parse(readFileSync(join(here, 'capacitor.config.json'), 'utf8'));
const app = join(here, 'android', 'app');
const main = join(app, 'src', 'main');
const res = join(main, 'res');

function edit(path, fn) {
  const before = readFileSync(path, 'utf8');
  const after = fn(before);
  if (after === before) throw new Error(`No change applied to ${path}`);
  writeFileSync(path, after);
}

// Permissions: Android 12+ scans without location (neverForLocation); 11 and older need location.
edit(join(main, 'AndroidManifest.xml'), (s) =>
  s
    .replace('<manifest xmlns:android="http://schemas.android.com/apk/res/android">',
      '<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n    xmlns:tools="http://schemas.android.com/tools">')
    .replace('<uses-permission android:name="android.permission.INTERNET" />', `<uses-permission android:name="android.permission.INTERNET" />
    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.BLUETOOTH_SCAN"
        android:usesPermissionFlags="neverForLocation" tools:targetApi="s" />
    <uses-permission android:name="android.permission.BLUETOOTH_CONNECT" tools:targetApi="s" />
    <uses-feature android:name="android.hardware.bluetooth_le" android:required="true" />`));

// Activity that keeps the screen on and hides the system bars.
const javaDir = join(main, 'java', ...config.appId.split('.'));
mkdirSync(javaDir, { recursive: true });
copyFileSync(join(here, 'MainActivity.java'), join(javaDir, 'MainActivity.java'));

// Version shown in Android settings; versionCode must grow for updates to install over the old app.
const versionName = process.env.VERSION_NAME || '0.0.0';
const versionCode = Number(process.env.VERSION_CODE || 1);
edit(join(app, 'build.gradle'), (s) =>
  s.replace(/versionCode \d+/, `versionCode ${versionCode}`).replace(/versionName "[^"]*"/, `versionName "${versionName}"`));

// Launcher icon: the dash icon instead of Capacitor's (drop the adaptive icon so the PNG is used).
rmSync(join(res, 'mipmap-anydpi-v26'), { recursive: true, force: true });
const icon = join(here, '..', 'icons', 'icon-192.png');
for (const dir of readdirSync(res).filter((d) => d.startsWith('mipmap-'))) {
  for (const name of ['ic_launcher.png', 'ic_launcher_round.png', 'ic_launcher_foreground.png']) {
    copyFileSync(icon, join(res, dir, name));
  }
}

// Splash: plain black instead of Capacitor's logo.
function blackPng() {
  const chunk = (type, data) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length);
    const body = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body) >>> 0);
    return Buffer.concat([len, body, crc]);
  };
  const ihdr = Buffer.from([0, 0, 0, 1, 0, 0, 0, 1, 8, 2, 0, 0, 0]); // 1x1, 8-bit RGB
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(Buffer.from([0, 0, 0, 0]))),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}
const black = blackPng();
for (const dir of readdirSync(res).filter((d) => d.startsWith('drawable'))) {
  const splash = join(res, dir, 'splash.png');
  if (existsSync(splash)) writeFileSync(splash, black);
}

console.log(`Patched Android project: ${config.appId} ${versionName} (${versionCode})`);
